for_loop.code:
// Standard C-style loop
int sum = 0;
for (int i=0; i<5; i++) {
  sum += i;
}

// SAC With-loop (data-parallel construct)
int[10] arr = with { 
  (. <= [i] <= .) : i * 2;
} : genarray([10], 0);

